from pathlib import Path
import json
E=Path('experiments/main-orc-backl-v5base');configs=json.loads((E/'author-config.json').read_text(encoding='utf-8-sig'))
for c in configs:
 old=json.loads(Path(c['beforeClip']).read_text(encoding='utf-8-sig'));c['before']=[]
 for f in old['frames']:
  p=f.get('png') or f.get('compositePng');c['before'].append('../../'+(p['path'] if isinstance(p,dict) else p))
html='''<!doctype html><meta charset="utf-8"><title>back_l — reconstrução v5</title><style>body{background:#222831;color:#eee;font:16px system-ui;margin:24px}button,select,input{font:inherit;margin:8px}canvas,img{image-rendering:pixelated;background:#373e49}main{display:flex;gap:24px;flex-wrap:wrap}figure{margin:0}figcaption{padding:8px}a{color:#aaddff}#hand{display:block;max-width:100%;height:auto}p{max-width:920px}</style><h1>back_l — Sword e Axe sobre v5</h1><p>TECHNICALLY_COMPLETE · VISUAL_REVIEW_REQUIRED · PENDING_CREATOR. Comparação V8 à esquerda / candidato à direita, 1×. Os punhos vêm do v5; diferenças de fase e holds precisam de julgamento do criador. <a href="report.md">Relatório e limitações</a> · <a href="pose-map.md">Mapa</a> · <a href="temporal-check.json">Checks</a></p><select id="category"><option value="0">Sword</option><option value="1">Axe</option></select><button id="play">Reproduzir</button><button id="prev">Anterior</button><button id="next">Próximo</button><select id="speed"><option>1</option><option>0.75</option><option>0.5</option></select><label><input type="checkbox" id="loop">Repetir</label><label><input type="checkbox" id="layersoff">Corpo sem armas</label><input type="range" id="frame" min="0" value="0"><p id="info"></p><main><figure><figcaption>V8 corrente</figcaption><canvas id="before" width="256" height="256"></canvas></figure><figure><figcaption>Candidato v5 retimado</figcaption><canvas id="after" width="256" height="256"></canvas></figure></main><h2>Punho 8×</h2><p>Original v5 / corpo layers-off / composto. Bookends desarmados não têm recorte armado.</p><img id="hand"><script>
const configs=CONFIG;const $=x=>document.getElementById(x);let ci=0,fi=0,running=false,elapsed=0,last=0;const cache=new Map();
function pic(src){if(!cache.has(src)){const im=new Image();im.src=src;im.onload=draw;cache.set(src,im)}return cache.get(src)}
function draw(){const c=configs[ci],f=c.frames[fi],fn=String(fi).padStart(2,'0')+'.png';$('frame').max=c.frames.length-1;$('frame').value=fi;$('info').textContent=`F${String(fi).padStart(2,'0')} · ${f.phase} · ${f.durationMs} ms · v5 F${String(f.sourceIndex).padStart(2,'0')} · ${f.weaponVisible?'armado':'desarmado'}${fi===c.contactEvent.frame?' · CONTATO':''}`;for(const [id,src]of [['before',c.before[fi]],['after',c.name+'/'+($('layersoff').checked?'layers/body':'frames')+'/'+fn]]){const ctx=$(id).getContext('2d');ctx.clearRect(0,0,256,256);const im=pic(src);if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}$('hand').hidden=!f.weaponVisible;if(f.weaponVisible)$('hand').src='hands-8x/'+c.name+'/'+fn;$('play').textContent=running?'Pausar':'Reproduzir'}
function stop(){running=false;elapsed=0}function select(i){stop();fi=i;draw()}
$('category').onchange=()=>{ci=+$('category').value;select(0)};$('frame').oninput=()=>select(+$('frame').value);$('next').onclick=()=>select(Math.min(fi+1,configs[ci].frames.length-1));$('prev').onclick=()=>select(Math.max(0,fi-1));$('layersoff').onchange=draw;$('play').onclick=()=>{if(fi===configs[ci].frames.length-1)fi=0;running=!running;elapsed=0;draw()};
function tick(now){const dt=last?now-last:0;last=now;if(running){elapsed+=dt*+$('speed').value;const c=configs[ci];while(running&&elapsed>=c.frames[fi].durationMs){elapsed-=c.frames[fi].durationMs;if(fi<c.frames.length-1)fi++;else if($('loop').checked)fi=0;else running=false;draw()}}requestAnimationFrame(tick)}draw();requestAnimationFrame(tick);
</script>'''
(E/'review.html').write_text(html.replace('CONFIG',json.dumps(configs,ensure_ascii=False)),encoding='utf-8')
